class SagaCoordinator:
    def __init__(self):
        self.steps = []  # List of dicts: {"name": str, "action": callable, "compensate": callable}
        self.execution_log = []

    def _validate_step(self, name, action, compensate):
        # Name must be a non‑empty string
        if not isinstance(name, str) or name == "":
            raise ValueError("Step name must be a non‑empty string")
        # Action and compensate must be callables and not booleans (bool is subclass of int, not callable)
        if not callable(action):
            raise ValueError(f"Action for step '{name}' must be callable")
        if not callable(compensate):
            raise ValueError(f"Compensate for step '{name}' must be callable")

    def add_step(self, name, action, compensate):
        """Register a step in the saga.

        Args:
            name (str): Unique identifier for the step.
            action (callable): Function that performs the forward operation. It receives the
                *context* dict and must return a result.
            compensate (callable): Function that undoes the action. It receives the same
                *context* dict.
        """
        self._validate_step(name, action, compensate)
        self.steps.append({"name": name, "action": action, "compensate": compensate})

    def _validate_context(self, context):
        # Context must be a dict (or subclass) and not a boolean or other primitive.
        if isinstance(context, bool) or not isinstance(context, dict):
            raise ValueError("Context must be a non‑boolean dictionary")

    def execute(self, context):
        """Execute all registered steps sequentially.

        If any step raises an exception, previously successful steps are compensated
        in reverse order. The method then raises ``SagaExecutionError`` containing the
        failing step name, the original exception, and a list of compensated step names.
        """
        self._validate_context(context)
        results = {}
        completed_steps = []  # Keep track of steps that succeeded
        try:
            for step in self.steps:
                step_name = step["name"]
                action = step["action"]
                # Execute the forward action
                result = action(context)
                results[step_name] = result
                completed_steps.append(step)  # Record successful step
            # All steps succeeded
            return {"success": True, "results": results}
        except Exception as original_error:
            # Begin compensation for previously completed steps in reverse order
            compensated = []
            # Include the step that failed? No, it didn't succeed, so we only compensate completed ones.
            for step in reversed(completed_steps):
                step_name = step["name"]
                compensate = step["compensate"]
                try:
                    compensate(context)
                    compensated.append(step_name)
                except Exception as comp_err:
                    # Compensation failure should not mask the original error but we log it.
                    # In a production system we would record this incident; here we continue.
                    compensated.append(f"{step_name}(compensation_failed)")
            # Raise saga error with details
            raise SagaExecutionError(step_name, original_error, compensated) from original_error
